            styleOverrides: {
                body: {
                    backgroundColor: lightPalette.background.default,
                    margin: 0,
                    padding: 0,
                    minHeight: '100vh',
                    transition: 'background-color 0.3s ease',
                    // Добавляем фоновое изображение для светлой темы
                    backgroundImage: `url('/img/background/background_light.png')`,
                    backgroundSize: 'cover',
                    backgroundPosition: 'center',
                    backgroundRepeat: 'no-repeat',
                    backgroundAttachment: 'fixed', // Фон фиксируется при прокрутке
                },
            },
        },

        // Стили для Paper (общий контейнер)
        MuiPaper: {
            styleOverrides: {
                root: {
                    borderRadius: shape.borderRadius,
                    transition: 'background-color 0.3s ease, box-shadow 0.3s ease',
                    // Делаем Paper полупрозрачным, чтобы был виден фон
