                    backdropFilter: 'blur(10px)', // Эффект размытия фона за Paper
                },
            },
        },
    },
};

// ============================================================================
// СБОРКА ТЕМНОЙ ТЕМЫ
// ============================================================================

export const darkThemeOptions: ThemeOptions = {
    palette: darkPalette,
    typography: typography,
    shape: shape,

    components: {
        ...darkCardTheme,
        ...darkButtonTheme,
        ...darkAppBarTheme,
        ...darkTypographyTheme,
        ...darkBadgeTheme,

        MuiCssBaseline: {
            styleOverrides: {
                body: {
                    backgroundColor: darkPalette.background.default,
                    margin: 0,
                    padding: 0,
                    minHeight: '100vh',
                    transition: 'background-color 0.3s ease',
                    // Добавляем фоновое изображение для темной темы
                    backgroundImage: `url('/img/background/background_dark.png')`,
                    backgroundSize: 'cover',
                    backgroundPosition: 'center',
                    backgroundRepeat: 'no-repeat',
                    backgroundAttachment: 'fixed', // Фон фиксируется при прокрутке
                },
            },
        },

        MuiPaper: {
            styleOverrides: {
                root: {
                    borderRadius: shape.borderRadius,
                    backgroundColor: 'rgba(30, 30, 30, 0.9)', // Полупрозрачный темный фон
                    backdropFilter: 'blur(10px)', // Эффект размытия фона за Paper
                    transition: 'background-color 0.3s ease, box-shadow 0.3s ease',
                },
            },
        },
    },
};

// Создаем готовые темы с помощью createTheme
export const lightTheme = createTheme(lightThemeOptions);
export const darkTheme = createTheme(darkThemeOptions);

// Экспортируем также отдельные части для возможного использования в компонентах
export { lightPalette, darkPalette, typography, shape };
